export const PYTHON_INFERENCE_CODE = "import numpy as np\nimport torch\n\nfrom eeg_denoiser.model import EEGDenoisingCNN\n\n\nclass EEGDenoiser:\n\n    def __init__(self, model_path=\"eeg_denoiser.pth\", device=None):\n\n        self.device = torch.device(\n            device or (\"cuda\" if torch.cuda.is_available() else \"cpu\")\n        )\n\n        self.model = EEGDenoisingCNN().to(self.device)\n\n        state = torch.load(\n            model_path,\n            map_location=self.device,\n            weights_only=True\n        )\n\n        self.model.load_state_dict(state)\n        self.model.eval()\n\n    def denoise(self, raw_signal):\n\n        signal = np.asarray(raw_signal, dtype=np.float32)\n\n        if signal.shape != (512,):\n            raise ValueError(\"Expected exactly 512 samples.\")\n\n        if not np.isfinite(signal).all():\n            raise ValueError(\"Signal contains invalid values.\")\n\n        scale = max(\n            float(np.sqrt(np.mean(signal ** 2))),\n            1e-6\n        )\n\n        normalized = signal / scale\n\n        tensor = torch.from_numpy(\n            normalized\n        ).reshape(1, 1, 512).to(self.device)\n\n        with torch.inference_mode():\n            output = self.model(tensor)\n\n        cleaned = output.cpu().numpy()[0, 0] * scale\n\n        return cleaned.astype(np.float32)";

export const PYTHON_MODEL_CODE = "import torch\nimport torch.nn as nn\n\n\nclass ResidualBlock(nn.Module):\n\n    def __init__(self, channels, dilation=1):\n        super().__init__()\n\n        self.conv1 = nn.Conv1d(\n            channels, channels,\n            kernel_size=9,\n            padding=4 * dilation,\n            dilation=dilation\n        )\n\n        self.activation = nn.GELU()\n\n        self.conv2 = nn.Conv1d(\n            channels, channels,\n            kernel_size=9,\n            padding=4\n        )\n\n    def forward(self, x):\n\n        residual = x\n\n        out = self.conv1(x)\n        out = self.activation(out)\n        out = self.conv2(out)\n\n        return self.activation(out + residual)\n\n\nclass EEGDenoisingCNN(nn.Module):\n\n    def __init__(self):\n        super().__init__()\n\n        self.input_layer = nn.Conv1d(\n            1, 32, kernel_size=9, padding=4\n        )\n\n        self.blocks = nn.Sequential(\n            ResidualBlock(32, dilation=1),\n            ResidualBlock(32, dilation=2),\n            ResidualBlock(32, dilation=4),\n            ResidualBlock(32, dilation=8),\n            ResidualBlock(32, dilation=1),\n            ResidualBlock(32, dilation=2)\n        )\n\n        self.output_layer = nn.Conv1d(\n            32, 1, kernel_size=9, padding=4\n        )\n\n        nn.init.zeros_(self.output_layer.weight)\n        nn.init.zeros_(self.output_layer.bias)\n\n    def forward(self, x):\n\n        features = self.input_layer(x)\n        features = self.blocks(features)\n\n        predicted_noise = self.output_layer(features)\n\n        return x - predicted_noise";
